const _byWilaya: Record<number, Commune[]> = {};
for (const c of COMMUNES) { (_byWilaya[c.wilaya_code] ??= []).push(c); }
export const COMMUNES_BY_WILAYA = _byWilaya;

export function getWilaya(code: number): Wilaya | undefined { return WILAYAS.find((w) => w.code === code); }
export function getCommunes(wilayaCode: number): Commune[] { return COMMUNES_BY_WILAYA[wilayaCode] ?? []; }
export function getCommune(id: number): Commune | undefined { return COMMUNES.find((c) => c.id === id); }
